description:
Design a write-back stage for a pipelined processor that captures data from the memory execution stage. The module transfers the data (me_memdata), destination register (me_td), and write enable signal (me_WREG) from the memory stage to the write-back stage, while also handling reset and stall conditions. Upon a reset, it initializes all outputs to zero. During a stall, it also clears the outputs, preventing any write-back actions until the stall is lifted. This ensures data integrity and proper timing within the pipelined architecture.
module top_module(
	clk,rst,stall,
	me_memdata, me_td, me_WREG,
	wb_memdata, wb_td, wb_WREG
    );

code:
module top_module(
	clk,rst,stall,
	me_memdata, me_td, me_WREG,
	wb_memdata, wb_td, wb_WREG
    );input clk,rst,stall;
	input wire [31:0] me_memdata;
	input wire [4:0] me_td;
	input wire me_WREG;
	output reg [31:0] wb_memdata;
	output reg [4:0] wb_td;
	output reg wb_WREG;

	always @(posedge clk or posedge rst)
	begin
	if(rst)
	begin
		wb_memdata <= 0;
		wb_td <= 0;
		wb_WREG <= 0;
	end
	else if(stall)
	begin
			wb_memdata <= 0;
			wb_td <= 0;
			wb_WREG <= 0;
	end
	else
	begin
		wb_memdata <= me_memdata;
		wb_td <= me_td;
		wb_WREG <= me_WREG;
	end
	end

endmodule

