module top_module(rst, wr_clk, rd_clk, din, wr_en, rd_en, dout, full, empty, prog_full);parameter ADDR_WIDTH = 7;
  parameter DATA_WIDTH = 16;
  parameter FIFO_DEPTH = 104;

  input rst;
  input wr_clk;
  input rd_clk;
  input [DATA_WIDTH-1:0] din;
  input wr_en;
  input rd_en;

  output [DATA_WIDTH-1:0] dout;
  output full;
  output empty;
  output prog_full;

  reg [DATA_WIDTH-1:0] fifo[FIFO_DEPTH-1:0];
  reg [ADDR_WIDTH-1:0] wr_ptr;
  reg [ADDR_WIDTH-1:0] rd_ptr;
  reg [ADDR_WIDTH-1:0] count;
  reg prog_full_reg;

  assign empty = (count == 0);
  assign full = (count == FIFO_DEPTH);
  assign prog_full = prog_full_reg;
  assign dout = fifo[rd_ptr];

  integer i; // Declare the loop variable

  always @(posedge wr_clk or negedge rst) begin
    if (~rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      prog_full_reg <= 0;
      for (i = 0; i < FIFO_DEPTH; i = i + 1) begin
        fifo[i] <= 0;
      end
    end else if (wr_en && ~full) begin
      fifo[wr_ptr] <= din;
      wr_ptr <= wr_ptr + 1;
      count <= count + 1;
      if (count == FIFO_DEPTH - 1) begin
        prog_full_reg <= 1;
      end
    end
  end

  always @(posedge rd_clk or negedge rst) begin
    if (~rst) begin
      wr_ptr <= 0;
      rd_ptr <= 0;
      count <= 0;
      prog_full_reg <= 0;
      for (i = 0; i < FIFO_DEPTH; i = i + 1) begin
        fifo[i] <= 0;
      end
    end else if (rd_en && ~empty) begin
      rd_ptr <= rd_ptr + 1;
      count <= count - 1;
      if (count == FIFO_DEPTH) begin
        prog_full_reg <= 0;
      end
    end
  end
endmodule

