module top_module(
    input signed [15:0] A,
    input signed [15:0] B,
    input clk, // Added clk input
    output signed [31:0] result
);reg signed [15:0] A_abs;
reg signed [15:0] B_abs;
reg signed [31:0] prod;
reg signed [31:0] result_reg;

// Absolute value of A
assign A_abs = (A < 0) ? -A : A;

// Absolute value of B
assign B_abs = (B < 0) ? -B : B;

// Pipeline registers
reg signed [31:0] prod_reg1;
reg signed [31:0] prod_reg2;

// Pipeline stage 1
always @(*) begin
    prod_reg1 = A_abs * B_abs;
end

// Pipeline stage 2
always @(posedge clk) begin
    prod_reg2 <= prod_reg1;
end

// Pipeline stage 3
always @(posedge clk) begin
    result_reg <= (A < 0) ^ (B < 0) ? -prod_reg2 : prod_reg2;
end

assign result = result_reg;

endmodule

