module binary_counter (
    input clk,
    input reset,
    output reg [9:0] count
);

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 10'b0000000000;
        end else begin
            count <= count + 10'b0000000001;
        end
    end
endmodule

