module counter_8bit (CLK, RESET, ENABLE, COUNT);
input CLK;
input RESET;
input ENABLE;
output reg [7:0] COUNT;

always @(posedge CLK or posedge RESET) begin
    if (RESET) begin
        COUNT <= 8'b00000000;
    end
    else if (ENABLE) begin
        COUNT <= COUNT + 1;
    end
end

endmodule

