  input                clk,
  input                rst_n,
  output reg  [7:0]    Q
);reg [7:0] shift_reg;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      shift_reg <= 8'b00000000;
      Q <= 4'b0000;
    end
    else begin
      shift_reg <= {shift_reg[6:0], shift_reg[7]};
      Q <= shift_reg[7:4];
      if (shift_reg == 8'b00000001) begin
        shift_reg <= 8'b10000000;
      end
      else if (shift_reg == 8'b00000011) begin
        shift_reg <= 8'b11000000;
      end
      else if (shift_reg == 8'b00000111) begin
        shift_reg <= 8'b11100000;
      end
      else if (shift_reg == 8'b00001111) begin
        shift_reg <= 8'b11110000;
      end
      else if (shift_reg == 8'b00011111) begin
        shift_reg <= 8'b11111000;
      end
      else if (shift_reg == 8'b00111111) begin
        shift_reg <= 8'b11111100;
      end
      else if (shift_reg == 8'b01111111) begin
        shift_reg <= 8'b11111110;
      end
      else if (shift_reg == 8'b11111111) begin
        shift_reg <= 8'b01111111;
      end
    end
  end

endmodule

