	.ENB(ce_b),
	.WEB(we_b),
	.DOB(),
	.DOPB()
);

`else








reg	[dw-1:0]	mem [(1<<aw)-1:0];	
reg	[aw-1:0]	addr_a_reg;		




assign do_a = (oe_a) ? mem[addr_a_reg] : {dw{1'b0}};




always @(posedge clk_a or posedge rst_a)
