module top_module(dout,
    empty,
    full,
    wr_en,
    wr_clk,
    rd_clk,
    din,
    rst,
    rd_en);output [7:0] dout;
  output empty;
  output full;
  input wr_en;
  input wr_clk;
  input rd_clk;
  input [7:0] din;
  input rst;
  input rd_en;

  reg [7:0] fifo [0:7];
  reg [2:0] write_ptr = 0;
  reg [2:0] read_ptr = 0;
  reg [2:0] count = 0;
  reg [2:0] next_write_ptr;    // Changed from wire to reg
  reg [2:0] next_read_ptr;     // Changed from wire to reg
  reg [2:0] next_count;         // Changed from wire to reg
  reg [7:0] next_dout;          // Changed from wire to reg
  wire next_empty;
  wire next_full;

  assign dout = next_dout;
  assign empty = next_empty;
  assign full = next_full;

  // Next state logic
  always @ (posedge wr_clk or posedge rd_clk) begin
    if (rst) begin
      write_ptr <= 0;
      read_ptr <= 0;
      count <= 0;
    end else begin
      write_ptr <= next_write_ptr;
      read_ptr <= next_read_ptr;
      count <= next_count;
    end
  end

  // Write logic
  always @ (posedge wr_clk) begin
    if (wr_en && !next_full) begin
      fifo[write_ptr] <= din;
      next_write_ptr <= write_ptr + 1;
      next_count <= count + 1;
    end else begin
      next_write_ptr <= write_ptr;
      next_count <= count;
    end
  end

  // Read logic
  always @ (posedge rd_clk) begin
    if (rd_en && !next_empty) begin
      next_dout <= fifo[read_ptr];
      fifo[read_ptr] <= 0;
      next_read_ptr <= read_ptr + 1;
      next_count <= count - 1;
    end else begin
      next_dout <= dout;
      next_read_ptr <= read_ptr;
      next_count <= count;
    end
  end

  // Empty and full logic
  assign next_empty = (count == 0);
  assign next_full = (count == 8);

endmodule

module top_module(

	input [31:0] x,
    input clk,
    output reg [6:0] seg,
    output reg [7:0] an,
    output wire dp 
	 );wire [2:0] s;	 
reg [3:0] digit;
wire [7:0] aen;
reg [19:0] clkdiv;

assign dp = 1;
assign s = clkdiv[19:17];
assign aen = 8'b11111111; 




always @(posedge clk)

	case(s)
	0:digit = x[3:0]; 
	1:digit = x[7:4]; 
	2:digit = x[11:8]; 
	3:digit = x[15:12]; 
	4:digit = x[19:16]; 
    5:digit = x[23:20]; 
    6:digit = x[27:24]; 
    7:digit = x[31:28]; 

	default:digit = x[3:0];

	endcase


	always @(*)

case(digit)




0:seg = 7'b1000000;
