module top_module (
	input clk,
	input areset,
	input x,
	output z);parameter HIGH=1, LOW=0;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= HIGH;
		else begin
			case (state)
				HIGH: state <= x ? HIGH : LOW;
				LOW: state <= LOW;
			endcase
		end
	end

	assign z = (state == HIGH && !x);

endmodule

