module top_module(
    aclr,
    data,
    rdclk,
    rdreq,
    wrclk,
    wrreq,
    q,
    rdempty,
    rdfull,
    rdusedw,
    wrfull,
    wrusedw
);input aclr;
input [15:0] data;
input rdclk;
input rdreq;
input wrclk;
input wrreq;
output [31:0] q;
output rdempty;
output rdfull;
output [14:0] rdusedw;
output wrfull;
output [15:0] wrusedw;

reg [31:0] buffer [511:0];
reg [9:0] wrptr = 0;
reg [9:0] rdptr = 0;
wire [9:0] wrptr_next = (wrptr == 511) ? 0 : wrptr + 1;
wire [9:0] rdptr_next = (rdptr == 511) ? 0 : rdptr + 1;

assign q = buffer[rdptr];
assign rdempty = (wrptr == rdptr);
assign rdfull = (wrptr_next == rdptr);
assign rdusedw = (wrptr >= rdptr) ? wrptr - rdptr : 512 - rdptr + wrptr;
assign wrfull = (wrptr_next == rdptr);
assign wrusedw = (rdptr > wrptr) ? rdptr - wrptr - 1 : 511 - wrptr + rdptr;

always @(posedge rdclk) begin
    if (rdreq && !rdempty) begin
        rdptr <= rdptr_next;
    end
end

always @(posedge wrclk) begin
    if (wrreq && !wrfull) begin
        buffer[wrptr] <= data;
        wrptr <= wrptr_next;
    end
    if (aclr) begin
        wrptr <= 0;
        rdptr <= 0;
    end
end

endmodule

