module fsm (
	input clk,
	input reset,
	input d,
	input f,
	output reg p);

	parameter F=0, G=1, S1=2, S2=3, S3=4;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= F;
		else state <= next;
	end

	always_comb begin
		case (state)
			F: next = d ? G : F;
			G: next = f ? S1 : S2;
			S1: next = f ? S2 : S3;
			S2: next = f ? S1 : F;
			S3: next = d ? G : F;
			default: next = 'x;
		endcase
	end

	assign p = (state == S1 && f);

endmodule

