    reg clk;
    reg d;
    reg f;
    reg reset;
    wire p;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    fsm dut (
        .clk(clk),
        .d(d),
        .f(f),
        .reset(reset),
        .p(p)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            d = 0;
            f = 0;
            reset = 1;
            @(posedge clk);
            #1;
            reset = 0;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %03d: f sequence (1, 1, 0), d=1", test_num);
            reset_dut();
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1;
            #1; #1;
 check_outputs(1'b1);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %03d: f sequence (1, 0, 1), d=1", test_num);
            reset_dut();
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1;
            #1; #1;
 check_outputs(1'b1);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %03d: f sequence (0, 1, 1), d=1", test_num);
            reset_dut();
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1;
            #1; #1;
 check_outputs(1'b1);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %03d: f sequence (1, 1, 1), d=1", test_num);
            reset_dut();
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1;
            #1; #1;
 check_outputs(1'b0);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %03d: f sequence (0, 1, 0), d=1", test_num);
            reset_dut();
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1;
            #1; #1;
 check_outputs(1'b0);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            $display("Testcase %03d: d drops to 0 during sequence", test_num);
            reset_dut();
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); d = 0; f = 1;
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1;
            #1; #1;
 check_outputs(1'b0);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            $display("Testcase %03d: Reset active in middle", test_num);
            reset_dut();
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1; f = 1;
            @(posedge clk); reset = 1;
            @(posedge clk); reset = 0; d = 1; f = 1;
            @(posedge clk); d = 1; f = 0;
            @(posedge clk); d = 1;
