module binary_counter(
  input clk,
  input rst_n,
  output reg [1:0] count
);

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      count <= 2'b00;
    end
    else begin
      if (count == 2'b11)
        count <= 2'b00;
      else
        count <= count + 1;
    end
  end

endmodule

